go
package main

import (
	"crypto/sha256"
	"encoding/hex"
	"fmt"
)

func hashToken(token string) string {
	hash := sha256.Sum256([]byte(token))
	return hex.EncodeToString(hash[:])
}

func main() {
	token := "pass1"
	hashedToken := hashToken(token)
	fmt.Println("Original Token:", token)
	fmt.Println("Hashed Token:", hashedToken)
}
